INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-03-004-1', 't-mm-03-004', 'document_html', '<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4071]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''><u><strong>             </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''><u><strong>RMI &lt; 200</strong></u></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4072]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>G</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>eneral</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''> Gyn</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>a</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>ecologist</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4073]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>OR</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4074]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>Gynecologist in cancer center</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4075]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>Symptomatic </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>Non simple</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>&gt; 5 cm</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>Multilocular</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>Bilateral</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''><strong>Consider surgery BSO.</strong></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4076]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''><u><strong>MDT Review</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>High likelihood </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>Of malignancy of</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>Ovary</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''><u><strong>Laparotomy </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''><u><strong>Staging by </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''><u><strong>Oncologist include:</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>1. laparotomy with clear documentation.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>2. cytolog</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>y of </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>washing/Ascites</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>3.TAH + BSO + omentectomy.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>4. Biopsy from suspicious areas.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>5. may include pelvic/abd</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>omen,</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>para-aortic</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>lymphadenectomy</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''><strong>BOT</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''> =&gt; Staging laparotomy by oncologist/ Gynaecologist according to MDT review.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''><u><strong>Cyst Aspiration:</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>25% sensitivity of cytological examination</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>To control symptoms if Pt is unfit for surgery.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>25% recurrence in 1 year after aspiration.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>New 2025 Update:</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>Simple, unilateral, unilocular, </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>Cystic lesion</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''> of </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''><u>&lt;</u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''> 3cm do not require routine follow up. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>Asymptomatic </span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4077]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>Any of 1 feature </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>Simple</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4078]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>Unilocular</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4079]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>Low like</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>lihood</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''> of ovarian malignancy</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>Laparotomy by trained Gynaecologist</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>&gt;</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>3cm - </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''><u>&lt;</u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''> 5cm</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4080]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>Unilateral </span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4081]" style="margin-left: 18pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>Consider conservative</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4082]" style="margin-left: 18pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>Treatment</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4083]" style="margin-left: 18pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>Reassessment after</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4084]" style="margin-left: 18pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>4 – 6m</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''><sup>0</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''> with TVS </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4085]" style="margin-left: 18pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>&amp; CA – 125.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4086]" style="margin-bottom: 8pt; margin-left: 18pt"> </p>
