INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-03-014-0', 't-mm-03-014', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-03-014" hidden></div>
<div class="mm-heading mm-h2 mm-header-banner mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4962]" style="background-color: #2F5496; color: #FFFFFF; padding: 6px 12px; border-radius: 4px; font-weight: 700; margin-top: 8pt; margin-bottom: 4pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">14.</span><span class="mm-list-body"><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>CA – VULVA:</strong></span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4963]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Urgent referral to Ca</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ncer </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>center</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> when there is suspicion don’t </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>wait</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> for the biopsy report.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4964]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>90% Seq cell CA.</span></span></div>
