INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-03-015-1', 't-mm-03-015', 'document_html', '<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5154]" style="margin-left: 18pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''><u><strong>Hysterectomy</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''><u><strong>:</strong></u></span></p>
