INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-04-010-0', 't-mm-04-010', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-04-010" hidden></div>
<div class="mm-heading mm-h2 mm-header-banner mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5635]" style="background-color: #2F5496; color: #FFFFFF; padding: 6px 12px; border-radius: 4px; font-weight: 700; margin-top: 8pt; margin-bottom: 4pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">4.</span><span class="mm-list-body"><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>SUI - STRESS URINARY INCONTINENCE &amp; ITS STEP WISE MANAGEMENT</strong></span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5636]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>1</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup><u><strong>st</strong></u></sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> line:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5637]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Life style:</strong></u></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5638]" style="padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>PFMT – 8 contractions </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>three time a day for</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 3m</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>0</sup></span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5639]" style="padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Supervised by physiotherapist.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5640]" style="padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Continue if effective.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5641]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Don’t use Electrical stimulation and/ or bio feed</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>back</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> alone or in combination with PFMT</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5642]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''color: #EE0000; font-family: "Calibri", sans-serif; font-size: 9pt''>Failed </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>should be considered if women can’t actively cont</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>r</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>act pelvic flour muscles to aid motivation and </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>adherence</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> to therapy.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5643]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>MDT:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5644]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>2</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup><u><strong>nd</strong></u></sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> line:</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> surgical treatment.</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5645]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">1.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Colposuspension ideal – space of </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Reitzes</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>, cooper’s ligament</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> either</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> trans</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>peritoneal</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> or </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> retroperitoneal.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5646]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">2.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Rectus Fascial sling.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5647]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">3.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Intra mural bulking agents.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5648]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>If other procedures are not suitable.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5649]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Permanent injectable material.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5650]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Less effective than surgery.</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5651]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">4.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Mid ureteral </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>mesh sling</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> procedures.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5652]" style="padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Retropubic </span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5653]" style="padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Tans obturator</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> not recommended unless previous surgery</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5654]" style="padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Type 1 macro porous polypropylene mesh.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5655]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">5.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Artificial </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>sphincters</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> = Not Recommended.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5656]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Unless surgery failed.</span></p>
