INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-04-011-0', 't-mm-04-011', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-04-011" hidden></div>
<div class="mm-heading mm-h2 mm-header-banner mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5697]" style="background-color: #2F5496; color: #FFFFFF; padding: 6px 12px; border-radius: 4px; font-weight: 700; margin-top: 8pt; margin-bottom: 4pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">5.</span><span class="mm-list-body"><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>URINARY RETENTION</strong></span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5698]" style="margin-bottom: 8pt"> </p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5699]" style="padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>MSU</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5700]" style="padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Cath</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>et</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>erize </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>for </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>24 – 48hrs.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5701]" style="padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>A</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ntibiotic</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> cover.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5702]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5703]" style="text-align: center"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Remove gradually</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5704]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5705]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pt voids                                               </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>D</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>on’t void.</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5706]" style="padding-left: 180pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Retain catheter for 7 days.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5707]" style="padding-left: 180pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>A/B cover.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5708]" style="padding-left: 180pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>CUE for infection.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5709]" style="padding-left: 180pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Rule out F.B or hematoma.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5710]" style="margin-left: 162pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5711]" style="margin-left: 162pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Don’t void after 7 days.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5712]" style="margin-left: 162pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5713]" style="margin-left: 162pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Refer to urologist or urogynaecologist.</span></p>
