INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-04-012-0', 't-mm-04-012', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-04-012" hidden></div>
<div class="mm-heading mm-h2 mm-header-banner mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5725]" style="background-color: #2F5496; color: #FFFFFF; padding: 6px 12px; border-radius: 4px; font-weight: 700; margin-top: 8pt; margin-bottom: 4pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">6.</span><span class="mm-list-body"><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>BLADDER PAIN SYNDROME</strong></span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5726]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Incidence 2.3 – 6.5%.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5727]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Diagnosis by exclusion</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5728]" style="margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> pain, pressure or discomfort + urgency/ frequency/ </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>nocturia</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>/ persistent urge to void.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5729]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5730]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Over 6 weeks – 6</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>months sometimes for years</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5731]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>With no </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>identifiable</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> cause.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5732]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>History:</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> RULE OUT</strong></u></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5733]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>UTI</span></span></div>
