INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-05-007-0', 't-mm-05-007', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-05-007" hidden></div>
<h2 class="mm-heading mm-h2 mm-header-banner" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6680]" style="background-color: #2F5496; color: #FFFFFF; padding: 6px 12px; border-radius: 4px; font-weight: 700; margin-top: 8pt; margin-bottom: 4pt; margin-left: 36pt"><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>8. UK MEDICAL ELIGIBILITY CRITERIA (UKMEC)</strong></span></h2>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6681]" style="margin-left: 18pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em>Definition </em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>of </strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>U</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>K</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>MEC </strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em>categories</em></span></p>
<div class="mm-table-scroll" role="region" tabindex="0"><table class="mm-table" style="border-collapse:collapse;margin-left:0pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;"><colgroup><col style="width:77.75pt;"><col style="width:446.5pt;"></colgroup><tbody><tr><td style="white-space:pre-wrap;width:77.75pt;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''><strong>UKMEC</strong></span></p></td><td style="white-space:pre-wrap;width:446.5pt;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''><strong>Definition of category</strong></span></p></td></tr><tr><td style="white-space:pre-wrap;width:77.75pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>Category 1</span></p></td><td style="white-space:pre-wrap;width:446.5pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>A condition for which there is no restriction for the use of the method</span></p></td></tr><tr><td style="white-space:pre-wrap;width:77.75pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>Category 2</span></p></td><td style="white-space:pre-wrap;width:446.5pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>A condition where the advantages of using the method generally outweigh the theoretical or proven risks</span></p></td></tr><tr><td style="white-space:pre-wrap;width:77.75pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>Category 3</span></p></td><td style="white-space:pre-wrap;width:446.5pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>A condition where the theoretical or proven risks usually outweigh the advantages of using the method. The provision of a method requires expert clinical judgement and/or referral to a specialist contraceptive provider, since use of the method is not usually recommended unless other more appropriate methods are not available or not acceptable</span></p></td></tr><tr><td style="white-space:pre-wrap;width:77.75pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>Category 4</span></p></td><td style="white-space:pre-wrap;width:446.5pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>A condition which represents an unacceptable health risk if the method is used</span></p></td></tr></tbody></table></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6682]" style="margin-bottom: 10pt"><span class="mm-run" style=''color: #44546A; font-family: "Calibri", sans-serif; font-size: 9pt''><em>Table </em></span><span class="mm-run" style=''color: #44546A; font-family: "Calibri", sans-serif; font-size: 9pt''><em>17</em></span><span class="mm-run" style=''color: #44546A; font-family: "Calibri", sans-serif; font-size: 9pt''><em>. </em></span><span class="mm-run" style=''color: #44546A; font-family: "Calibri", sans-serif; font-size: 9pt''><em>UKMEC SUMMARY TABLE HORMONAL AND INTRAUTERINE CONTRACEPTION:</em></span></p>', 0);
