INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-05-008-0', 't-mm-05-008', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-05-008" hidden></div>
<h2 class="mm-heading mm-h2 mm-header-banner" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6715]" style="background-color: #2F5496; color: #FFFFFF; padding: 6px 12px; border-radius: 4px; font-weight: 700; margin-top: 8pt; margin-bottom: 4pt; margin-left: 18pt"><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>9. COMBINED HORMONAL CONTRACEPTION</strong></span></h2>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6716]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">✓</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1/3’</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>d </sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>UK women aged 16—44 years had used oral contraception</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6717]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">✓</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>CHC -estrogen and a progestogen</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6718]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u>A pill (COC)</u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6719]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Transdermal Patch CTP</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6720]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Vaginal ring CVR</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6721]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>PERFECT USE VS TYPICAL USE</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6722]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Many contraceptive methods are affected by human error such as forgetting to take your pill. They may be very effective with "perfect use" but the effectiveness of certain methods as "typically used" is likely to be lower. </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6723]" style="margin-bottom: 8pt"><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''><u><em><strong>Perfect use:</strong></em></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> of a contraceptive method is when it is used correctly all the time. </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6724]" style="margin-bottom: 8pt"><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''><u><em><strong>Typical use</strong></em></u></span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>: </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>is what generally happens in real life. It takes into account human error.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6725]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Segoe UI Symbol", sans-serif; font-size: 12pt''>✓</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> Effectiveness could also be affected by drug interactions (all CHC methods) and malabsorption (COC only). </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>CONTRACEPTIVE EFFECTIVENESS:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6726]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>CHC is highly user-dependent:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6727]" style="margin-bottom: 8pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6728]"><span class="mm-run" style=''font-family: "Segoe UI Symbol", sans-serif; font-size: 12pt''>✓</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>CTP could be less effective in women weighing &gt;90 kg</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> Perfect use = </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u>contraceptive</u></span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Typical use it is estimated that</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6729]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u>failure is low (&lt;1%).</u></span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u>9% of women have unplanned</u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6730]"><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u>pregnancies in the first year of CHC use</u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6731]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''><u><strong>Health risks:</strong></u></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6732]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''><u>VTE:</u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''> CHC is associated with increased risk of VTE;</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6733]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>dependent on progestogen type</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''> and estrogen dose</span></span></div>
<div class="mm-table-scroll" role="region" tabindex="0"><table class="mm-table" style="border-collapse:collapse;margin-left:0pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;"><colgroup><col style="width:233.75pt;"><col style="width:233.75pt;"></colgroup><tbody><tr><td style="white-space:pre-wrap;width:233.75pt;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''><strong>Type of CHC used</strong></span></p></td><td style="white-space:pre-wrap;width:233.75pt;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''><strong>Risk of developing a VTE in a year (incidence in 10 000 women)</strong></span></p></td></tr><tr><td style="white-space:pre-wrap;width:233.75pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>Women not using combined hormonal pill/patch/ring and not pregnant</span></p></td><td style="white-space:pre-wrap;width:233.75pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>~2</span></p></td></tr><tr><td style="white-space:pre-wrap;width:233.75pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>Women using CHC containing levonorgestrel, norethisterone or norgestimate</span></p></td><td style="white-space:pre-wrap;width:233.75pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>-5-7</span></p></td></tr><tr><td style="white-space:pre-wrap;width:233.75pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>Women using CHC containing etonogestrel or norelgestromin</span></p></td><td style="white-space:pre-wrap;width:233.75pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>~6-12</span></p></td></tr><tr><td style="white-space:pre-wrap;width:233.75pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>Women using CHC containing drospirenone, gestodene or desogestrel</span></p></td><td style="white-space:pre-wrap;width:233.75pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>~9-12</span></p></td></tr></tbody></table></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6734]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Arterial thromboembolic disease:</strong></span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6735]" style="margin-bottom: 8pt; margin-left: 72pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Myocardial inform</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>a</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>tion (MI) and ischemic stroke</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6736]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Breast cancer:</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> small increased risk of breast cancer which reduces with time after stopping CHC.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6737]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Cervical cancer:</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> current use of CHC for &gt; 5 years has a small increased risk of cervical cancer risk reduces over time after stopping CHC and is no longer increased by about 10 years after stopping.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6738]" style="margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u>Hormone free interval HFI can be associated with </u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u>these defects</u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u> including mood chance headache and unscheduled bleeding.</u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6739]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Concomitant use of other drugs:</strong></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6740]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Hepatic enzyme-inducing drugs could reduce</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> the </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>contraceptive effectiveness of all CHC methods. It can affect serum levels of drugs such as lamotrigine with potential significant clinical effects</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6741]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Choice of contraceptive method</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>:</strong></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6742]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>A COC containing &lt; 30 ug EE in combination with LNG or NET is a reasonable first-line option to minimize (VTE) risk.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6743]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 13pt''><u><strong>CHC, formulation and regimen</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 13pt''><u><strong>:  </strong></u></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6744]" style="margin-bottom: 8pt; padding-left: 54pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Estrogens:</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> In the UK, the majority of COC as well as the CTP and CVR, contain between 20 µg and 35 µg of the synthetic estrogen, EE. </span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6745]" style="margin-bottom: 8pt; padding-left: 54pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Progestogens: </strong></span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6746]" style="margin-bottom: 8pt; padding-left: 54pt"><span class="mm-list-marker" aria-hidden="true">⮤</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>First: norethisterone (NET) </span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6747]" style="margin-bottom: 8pt; padding-left: 54pt"><span class="mm-list-marker" aria-hidden="true">⮤</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Second: levonorgestrel (LNG) </span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6748]" style="padding-left: 54pt"><span class="mm-list-marker" aria-hidden="true">⮤</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Third: </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Desogestrel</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>, </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>gestagens</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>, norgestimate</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6749]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Newer/</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Formulations</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>: </strong></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6750]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Co-cyprindiol (containing 35 µg EE with cyproterone acetate, an anti-androgen) is indicated for management of moderate to severe acne and hirsutism. Women using co-cyprindiol for these indications do not require additional contraception.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6751]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong> Standard and tailored regimens for use of combined hormonal contraception (CHC)</strong></span></p>
<div class="mm-table-scroll" role="region" tabindex="0"><table class="mm-table" style="border-collapse:collapse;margin-left:36pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;"><colgroup><col style="width:155.8pt;"><col style="width:155.85pt;"><col style="width:155.85pt;"></colgroup><tbody><tr><td style="white-space:pre-wrap;width:155.8pt;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;padding-left:36pt;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''><strong>Type of regimen</strong></span></p></td><td style="white-space:pre-wrap;width:155.85pt;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;padding-left:36pt;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''><strong>Period of CHC use</strong></span></p></td><td style="white-space:pre-wrap;width:155.85pt;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;padding-left:36pt;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''><strong>HFI</strong></span></p></td></tr><tr><td style="white-space:pre-wrap;width:155.8pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;padding-left:36pt;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>Standard use </span></p></td><td style="white-space:pre-wrap;width:155.85pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>21 days (21 active pills or 1 ring, or 3 patches) </span></p></td><td style="white-space:pre-wrap;width:155.85pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;padding-left:36pt;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>7 days</span></p></td></tr><tr><td style="white-space:pre-wrap;width:155.8pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;padding-left:36pt;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>Tailored use </span></p></td><td style="white-space:pre-wrap;width:155.85pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;padding-left:0pt;margin-bottom:8pt;"></p></td><td style="white-space:pre-wrap;width:155.85pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;padding-left:0pt;margin-bottom:8pt;"></p></td></tr><tr><td style="white-space:pre-wrap;width:155.8pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>Shortened hormone-free interval (HFI) </span></p></td><td style="white-space:pre-wrap;width:155.85pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;padding-left:36pt;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>21 days</span><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''> (21 active pills or 1 ring, or 3 patches) </span></p></td><td style="white-space:pre-wrap;width:155.85pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;padding-left:36pt;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>4 days</span></p></td></tr><tr><td style="white-space:pre-wrap;width:155.8pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>Extended use (tricycling) </span></p></td><td style="white-space:pre-wrap;width:155.85pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>9 weeks 3 x 21 active pills or 3 rings, or 9 patches used consecutively) </span></p></td><td style="white-space:pre-wrap;width:155.85pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>4 or 7 days</span></p></td></tr><tr><td style="white-space:pre-wrap;width:155.8pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;padding-left:36pt;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>Flexible extended use </span></p></td><td style="white-space:pre-wrap;width:155.85pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>Continuous use (</span><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>&gt;</span><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>221 days) of active pills, patches or rings until breakthrough bleeding occurs for 3-4 days </span></p><p style="margin:0;padding-left:0pt;margin-bottom:8pt;"></p></td><td style="white-space:pre-wrap;width:155.85pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;padding-left:36pt;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>4 days</span></p><p style="margin:0;text-align:center;padding-left:0pt;margin-bottom:8pt;"></p></td></tr><tr><td style="white-space:pre-wrap;width:155.8pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;padding-left:36pt;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>Continuous use </span></p><p style="margin:0;padding-left:0pt;margin-bottom:8pt;"></p></td><td style="white-space:pre-wrap;width:155.85pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;padding-left:36pt;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>Continuous use of active pills, patches or rings </span></p></td><td style="white-space:pre-wrap;width:155.85pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;padding-left:36pt;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>None</span></p><p style="margin:0;text-align:center;padding-left:0pt;margin-bottom:8pt;"></p></td></tr></tbody></table></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6752]" style="margin-bottom: 8pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6753]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 16pt''><u><strong>Studies</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 16pt''><u><strong> revealed that suppression of ovarian activity with low-dose COCs with 7-day HFIs is suboptimal. Loss of ovarian suppression during 7-day HFIs is commonly associated with follicular development, and</strong></u></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6754]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>most dominant follicles appear during this period. By contrast, increased ovarian suppression was noted in regimens that shortened or eliminated the HFI, or that substituted low-dose ethinyl estradiol for the HFI. </span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6755]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Extended regimens with modified HFIs may provide greater ovarian suppression with the potential for increased contraceptive effectiveness. </span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6756]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Non-contraceptive health benefits: </strong></u></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6757]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">✓</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Reduce HMB </span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6758]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">✓</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>menstrual pain </span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6759]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">✓</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>improve acne. </span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6760]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">✓</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Premenstrual syndrome symptoms. </span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6761]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">✓</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Reduce risk of recurrence of endometriosis after surgical management. </span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6762]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">✓</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>CHC can be used for management of pcos. </span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6763]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">✓</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Significant reduction in risk of endometrial and ovarian cancer that increases with duration of chc use and persists for many years after stopping chc </span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6764]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">✓</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Reduced </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>risk of colorectal cancer</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6765]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6766]" style="margin-bottom: 10pt"><span class="mm-run" style=''color: #44546A; font-family: "Calibri", sans-serif; font-size: 9pt''><em>Table </em></span><span class="mm-run" style=''color: #44546A; font-family: "Calibri", sans-serif; font-size: 9pt''><em>18</em></span><span class="mm-run" style=''color: #44546A; font-family: "Calibri", sans-serif; font-size: 9pt''><em>. </em></span><span class="mm-run" style=''color: #44546A; font-family: "Calibri", sans-serif; font-size: 9pt''><em>Starting combined hormonal contraception and requirement for additional contraceptive precautions</em></span></p>', 0);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-05-008-1', 't-mm-05-008', 'document_html', '<div class="mm-table-scroll" role="region" tabindex="0"><table class="mm-table" style="border-collapse:collapse;margin-left:0pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;"><colgroup><col style="width:120.25pt;"><col style="width:134.65pt;"><col style="width:155.95pt;"><col style="width:92.15pt;"></colgroup><tbody><tr><td style="white-space:pre-wrap;width:120.25pt;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''><strong>Circumstance</strong></span></p></td><td style="white-space:pre-wrap;width:134.65pt;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''><strong>When to start</strong></span></p></td><td style="white-space:pre-wrap;width:155.95pt;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''><strong>Requirement for 7 days additional contraceptive precautions (9 days for estradiol valerate/dienogest COC)</strong></s