INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-05-020-0', 't-mm-05-020', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-05-020" hidden></div>
<h2 class="mm-heading mm-h2 mm-header-banner" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[7645]" style="background-color: #2F5496; color: #FFFFFF; padding: 6px 12px; border-radius: 4px; font-weight: 700; margin-top: 8pt; margin-bottom: 4pt; margin-left: 18pt"><span class="mm-run" style=''color: #FFFFFF; font-family: "Times New Roman", sans-serif; font-size: 16pt''><strong>21. CONTRACEPTON FOR YOUNG POPULATION:</strong></span></h2>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[7646]" style="margin-top: 5pt; margin-bottom: 5pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''><strong>UK Medical Eligibility Criteria (UKMEC) for Contraceptive Use – Based on Age</strong></span></span></div>
<div class="mm-table-scroll" role="region" tabindex="0"><table class="mm-table" style="border-collapse:collapse;margin-left:0pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;"><colgroup><col style="width:309.4pt;"><col style="width:123.3pt;"><col style="width:95.2pt;"></colgroup><tbody><tr data-mm-row-height-twips="490" data-mm-row-height-rule="auto"><td style="white-space:pre-wrap;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Times New Roman", sans-serif;font-size:12pt''><strong>Method</strong></span></p></td><td style="white-space:pre-wrap;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Times New Roman", sans-serif;font-size:12pt''><strong>Age</strong></span></p></td><td style="white-space:pre-wrap;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Times New Roman", sans-serif;font-size:12pt''><strong>UKMEC Category</strong></span></p></td></tr><tr><td style="white-space:pre-wrap;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Times New Roman", sans-serif;font-size:12pt''><strong>Combined hormonal contraception</strong></span><span class="mm-run" style=''font-family:"Times New Roman", sans-serif;font-size:12pt''> (oral, vaginal ring, patch)</span></p></td><td style="white-space:pre-wrap;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Times New Roman", sans-serif;font-size:12pt''>Menarche to &lt;40 years</span></p></td><td style="white-space:pre-wrap;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Times New Roman", sans-serif;font-size:12pt''>1</span></p></td></tr><tr><td style="white-space:pre-wrap;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"></p></td><td style="white-space:pre-wrap;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Times New Roman", sans-serif;font-size:12pt''>≥40 years</span></p></td><td style="white-space:pre-wrap;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padd