INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-07-005-0', 't-mm-07-005', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-07-005" hidden></div>
<h2 class="mm-heading mm-h2 mm-header-banner" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10352]" style="background-color: #2F5496; color: #FFFFFF; padding: 6px 12px; border-radius: 4px; font-weight: 700; margin-top: 8pt; margin-bottom: 4pt"><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>5. MANAGEMENT OF NAUSEA AND VOMITING IN PREGNANCY AND HYPEREMESIS GRAVIDARUM:</strong></span></h2>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10353]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>NVP = 90 % of pregnancies.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10354]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Onset before 16 weeks</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10355]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>HG = 0.3 – 3.6%</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> (</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Severe form of NVP</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>)</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10356]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Mechanism:</strong></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10357]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Hypersensitivity to vomiting hormone growth differentiation factor 15 IGDF – 15</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10358]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>HCG</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10359]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Genetic pr</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>e</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>disposition.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10360]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Diagnosis of NVP</strong></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10361]" style="padding-left: 54pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Onset: 4 -7 weeks</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10362]" style="padding-left: 54pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Peak: 9 weeks.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10363]" style="margin-bottom: 8pt; padding-left: 54pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Settles: 20 weeks in 90% women.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10364]" style="margin-bottom: 8pt; padding-left: 54pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Rule out other causes. </span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10365]" style="margin-bottom: 8pt; padding-left: 54pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Onset must be before 16 weeks.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10366]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u>Onset after</u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 10</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>+6</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> weeks =&gt; less likely NVP.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10367]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>HG:</strong></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10368]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">1.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Severe NVP affecting daily activity</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10369]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">2.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Inability to eat or drink</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10370]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">3.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Dehydration. </span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10371]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">4.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Ketonuria</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> is no longer used</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10372]" style="margin-left: 18pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Severity of NVP</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10373]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>        1.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Objective and validated index</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10374]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>        2.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>PUQE</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> SCORE</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10375]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>PUQE index also track response to treatment for mild &amp; moderate but not severe and HG</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10376]" style="margin-bottom: 8pt; margin-left: 18pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''> 3.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>HELP – can be used to track response to treatment in severe NV and HG.</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10377]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''><strong>PUQE score(24</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''><strong>HRS</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''><strong>):</strong></span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10378]" style="padding-left: 54pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>Mild = up to 6.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10379]" style="padding-left: 54pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>Mod</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>erate</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''> = 7 – 12.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10380]" style="margin-bottom: 8pt; padding-left: 54pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>Severe = 13 – 15.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10381]" style="margin-top: 5pt; margin-bottom: 5pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10382]" style="margin-bottom: 8pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10383]" style="margin-bottom: 8pt"> </p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10384]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>HELP Score:</strong></span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10385]" style="margin-bottom: 8pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10386]" style="margin-bottom: 8pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10387]" style="margin-bottom: 8pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10388]" style="margin-bottom: 8pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10389]" style="margin-bottom: 8pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10390]" style="margin-bottom: 8pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10391]" style="margin-bottom: 8pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10392]" style="margin-bottom: 8pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10393]" style="margin-bottom: 8pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10394]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 13pt''><u><strong>Assessment</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10395]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Investigation:</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Dipstick</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Nitrate shows infection</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>MSU</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Urea/Electrolyte</span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Hypo/Kalemia</span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Hyponatremia</span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>.</span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Hypochloremi</span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>c</span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>alkalosis</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>CBC</span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Infection TLC</span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>HCT - raised</span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Anemia </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>BSR</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> – rule out DKA</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>USG</span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Confirm viable pregnancy.</span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Exclude multiple &amp; molar pregnancy</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Refractory cases:</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>TFTS 2/3</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>rd</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> have abnormal TFTS.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>LFTS 40% of </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>NVP</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>have abnormal LFTS, most commonly transaminases </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Ca</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>lcium </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>phosphate</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Amylase</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>, to exclude pancreatitis</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ABG</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> to exclude metabolic disturbance.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>History:</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>previous NVP, HG</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>PUQE score</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>/ HELP score</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Exclude</span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Abd</span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>ominal</span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''> pain</span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>pancreatitis</span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>UTI, other infections</span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>chronic H </span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>pylori</span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''> infection. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Severe abd</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ominal or </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>epigastric</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> pain is unusual – rule out other cases.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Endoscopy </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>is </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>safe.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Rule out comorbidities</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>D/</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>D:</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Cholecystitis</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>pancreatitis</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>UTI, pyelonephritis</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Hepatitis </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Drug </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>induced</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Neurological conditions</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Examination:</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>B.P</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pulse</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Temp</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>R/R</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>O</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sub>2</sub></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> sa</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>t </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Dehydration signs</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Muscle wasting</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Weight</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Obs examination</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Neurological signs</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Malnutrition signs</span></p>
