INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-07-007-0', 't-mm-07-007', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-07-007" hidden></div>
<h2 class="mm-heading mm-h2 mm-header-banner" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10668]" style="background-color: #2F5496; color: #FFFFFF; padding: 6px 12px; border-radius: 4px; font-weight: 700; margin-top: 8pt; margin-bottom: 4pt; margin-left: 18pt"><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>7. </strong></span><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong> AMNIOCENTESIS &amp; CVS:</strong></span></h2>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10669]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>5% women require invasive Tests or 300,000/Anum.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10670]" style="margin-bottom: 8pt; margin-left: 36pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10671]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 16pt''><u><strong> Amniocentesis</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>: </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Most common</strong></u></span></p>
