INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-08-003-1', 't-mm-08-003', 'document_html', '<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[11331]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>HIGH RISK</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>At least 6 weeks’</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> postnatal prophylactic LMWH</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>(to be assessed on delivery suite).</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[11332]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Any previous VTE.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Anyone requiring antenatal LMWH</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>High risk thrombophilia</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Low risk thrombophilia + FHx</span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Score 4 or more</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[11333]" style="margin-bottom: 8pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[11334]" style="margin-bottom: 8pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[11335]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>INTEREDIATE RISK</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>At least 10 days</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Postnatal</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> prophylactic LMWH</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>NB persisting or &gt; 3 risk factors, consider extending </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>thromboprophylaxis</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> with LMWH.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Caesarean section in labour. (2)</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>BMI </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u>&gt;</u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 40 kg/m</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>2</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Readmission or prolonged admission (</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u>&gt;</u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 3 days) in the puerperium</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Any surgical procedure in the puerperium except immediate repair of the perineum. (3)</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Medical comorbidities e.g. cancer, heart failure, active SLE, IBD or inflammatory polyarthropathy, nephrotic syndrome, type IDM with nephropathy, sickle cell disease, current IVDU</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[11336]" style="margin-bottom: 8pt"><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 9pt''>Score 2 or 3</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[11337]" style="margin-bottom: 8pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[11338]" style="margin-bottom: 8pt"> </p>
