INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-09-002-0', 't-mm-09-002', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-09-002" hidden></div>
<h3 class="mm-heading mm-h3 mm-header-banner" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15685]" style="background-color: #9CC2E5; color: #FFFFFF; padding: 6px 12px; border-radius: 4px; font-weight: 700; margin-top: 8pt; margin-bottom: 4pt"><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>1.1.</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>GBS IN PREGNANCY:</span></h3>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15686]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>in UK 0.5/100.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15687]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>anten</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>atal </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>screening </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>is</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> done @</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>35 – 37 in singleton, 32 – 34 </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>in </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>twins.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15688]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Incidence of GBS carriage = 20-40% of bowel flora. </span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15689]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Incidence of GBS:</strong></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15690]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Overall = 0.57/1000.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15691]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Without risk factor = 0.2/ 1000.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15692]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>In previous pregnancy = 0.9/ 1000.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15693]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>If GBS in current pregnancy = 2.3/ 1000.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15694]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pyrexia &gt; 38 = 5.3/ 1000.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15695]" style="margin-bottom: 8pt; margin-left: 18pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>EONNS:</strong></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15696]" style="margin-bottom: 8pt; padding-left: 54pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Early onset Neonatal sepsis &lt; 7 days </span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15697]" style="margin-bottom: 8pt; padding-left: 54pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>89% within 24hours.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15698]" style="margin-bottom: 8pt; padding-left: 54pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>97% within 12 hours.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15699]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Mortality of EONNS = 10.6% overall</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15700]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">1.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>&gt;37 weeks = 5.7%</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15701]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">2.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>&lt;37 weeks = 18.3%</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15702]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">3.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>&lt;35 weeks = 22%</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15703]" style="margin-bottom: 8pt; margin-left: 18pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Late:</strong></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15704]" style="margin-bottom: 8pt; padding-left: 54pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>7 and above days.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15705]" style="margin-bottom: 8pt; padding-left: 54pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>17 – 25% screen positive @ 35 – 37 weeks will be negative @ delivery.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15706]" style="margin-bottom: 8pt; padding-left: 54pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>5 – 7% screen negative will be </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>positive </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>@ birth.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15707]" style="margin-bottom: 8pt; padding-left: 54pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>No screening on maternal request.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15708]" style="margin-bottom: 8pt; padding-left: 54pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>GBS carriage PROM =&gt; </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>cat</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>egory</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 2/3 C/S </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>if required</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15709]" style="margin-bottom: 8pt; margin-left: 18pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Antenatal A</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>ntibiotics</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>:</strong></em></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15710]" style="margin-bottom: 8pt; padding-left: 54pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>GBS bacteriuria (Antenatal + IAP).</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15711]" style="margin-bottom: 8pt; padding-left: 54pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Membrane sweeping is not C/I.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15712]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Commonest Cause GBS:</strong></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15713]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>streptococcus agalactiae.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15714]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>E – Coli.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15715]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Meningitis = 11.8%.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15716]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pneumonia = 7.8%.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15717]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Focal infection = 1%.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15718]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Risk Factor for GBS:</strong></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15719]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Previous baby GBS.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15720]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>GBS carriage.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15721]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pre – term.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15722]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Prolong rupture of membranes &gt; 18 hours.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15723]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Suspected maternal infection.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15724]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pyrexia </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u>&gt;</u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 38</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>0</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>C.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15725]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Indications of GBS IAP (80% Effective):</strong></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15726]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">1.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Previous baby with invasive GBS.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15727]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">2.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>GBS </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>bacteriuria</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 10</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>5</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>cfu/ml in current pregnancy.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15728]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">3.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>GBS on vaginal sw</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>a</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>b in current pregnancy.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15729]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">4.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pyrexia &gt; 38</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>0</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>F (Broad spectrum A/B).</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15730]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">5.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Chorioamni</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>oniti</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>s</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> (Broad Spectrum A/B) @ PTL.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15731]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>GBS carriage in previous pregnancy either IAP or screening @ 35 – 37 weeks.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15732]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Repeat colonization = 50%.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15733]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Repeat GBS = 0.9/ 1000.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15734]" style="margin-bottom: 8pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15735]" style="margin-bottom: 8pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15736]" style="margin-bottom: 8pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15737]" style="margin-bottom: 8pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15738]" style="margin-bottom: 8pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15739]" style="margin-bottom: 8pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15740]" style="margin-bottom: 8pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15741]" style="margin-bottom: 8pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15742]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''><strong> intrapartum antibiotic prophylaxis (IAP)</strong></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15743]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''>Benzyl penicillin 3g stat </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''>followed by </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''>1.5g 4</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''>hourly</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''> till delivery</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''>.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15744]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''>clinda</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''>mycin</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''> 900g stat </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''>then</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''> 8 hourly</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''> till delivery (</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''>resistance = 16%</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''>)</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15745]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''>Vanc</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''>o</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''>mycin</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''> 1g – 12 hourly, if severe </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''>allergy</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''> to Benzyl Penicillin </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''>(</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''>Angioedema, </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''>urticaria</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''> anaphylaxis, RDS</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''>)</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''>.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15746]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Cefuroxim</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>e 1</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.5</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>g stat </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>then</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 750g – 8 h</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ourly if mild allergy to Benzyl</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> Penicillin</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15747]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pt refuses IAP =&gt; Observe baby for 12 hours.</span></span></div>
