INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-09-006-0', 't-mm-09-006', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-09-006" hidden></div>
<h3 class="mm-heading mm-h3 mm-header-banner" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16171]" style="background-color: #9CC2E5; color: #FFFFFF; padding: 6px 12px; border-radius: 4px; font-weight: 700; margin-top: 8pt; margin-bottom: 4pt"><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>1.5. MALARIA IN PREGNANCY</span></h3>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16172]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Tertian Malaria –</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 48 hours’ cycle – P oval</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>e</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>, vivax, falciparum</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16173]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Quartan</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong> Malaria –</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 72 hours’ cycle – P Malariae.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16174]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Immunity lost</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> within 2 years.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16175]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Gold std</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong> Test</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>:</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> microscopic examination of thick &amp; thin film.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16176]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Incidences:</strong></u></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16177]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>75% falciparum, 0.5 – 1% Mortality</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16178]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>5.5% ovale 12.9% vivax, 2.1% Malaria</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>e</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16179]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Suspect malaria:</strong></u></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16180]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Fe</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ver</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> + history of travel </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>to endemic area </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>or residence (&gt; 6m</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>0</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>).</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16181]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Recent return 3 weeks – viral infections.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16182]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Chemoprophylaxis not 100% effective.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16183]" style="margin-bottom: 8pt; margin-left: 36pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16184]" style="margin-bottom: 8pt; margin-left: 36pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16185]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>S/S + investigations – Rapid Testing + blood film (1 hour).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16186]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Other Tests –</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> CBC, BSL, U/E, blood C/S, urine dip, stool, CXR, USG.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16187]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Blood film shows:</strong></u></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16188]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">1.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em>No evidence of Malaria.</em></span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16189]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">2.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em>Falciparum.</em></span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16190]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">3.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em>Non</em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em>-Falciparum</em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em>.</em></span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16191]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>1. No evidence of Malaria:</strong></u></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16192]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Repeat film – (after stopping prophylaxis).</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16193]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>3 </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>negative </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>films 12 – 24 </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>hours</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16194]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>a</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>part exclude malaria so</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> f</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>inish chemoprophylaxis.</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16195]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Empirical</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> Treatment – Severe malaria expected.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16196]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Stop prophylaxis before repeating (as it give negative report).</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16197]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>2. Non – Falciparum:</strong></u></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16198]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Chloroquine – 600mg stat dose</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16199]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>300mg – 6 – 8 hours later.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16200]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>300mg – D</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ay </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>2.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16201]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>300mg – D</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ay </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>3.</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16202]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>To prevent relapse (vivax/ovale).</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16203]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>300mg – weekly chloroquine.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16204]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>During pregnancy chloroquine resistant cases are treated by mefloquine.</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16205]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>To prevent relapse </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>after delivery</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> and testing for G</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>6</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>PD </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>,</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>primaquine is recommended</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>. (avoid in pregnancy).</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16206]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>3. Falciparum:</strong></u></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16207]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Mixed species or not characterized.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16208]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Admit.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16209]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Assess severity.</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16210]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">→</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Complicated.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16211]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">→</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Uncomplicated.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16212]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Complicated:</strong></u></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16213]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Admit in HDU</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16214]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>&gt;</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>2% </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>parasitized</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16215]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>50% mortality.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16216]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Antimalarial immediately.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16217]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Fluid balance – </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>CVP </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>line.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16218]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Monitoring.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16219]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>BSL – 1 hourly</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16220]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>4 hourly</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16221]" style="margin-bottom: 8pt; padding-left: 108pt"><span class="mm-list-marker" aria-hidden="true">→</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>HR.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16222]" style="margin-bottom: 8pt; padding-left: 108pt"><span class="mm-list-marker" aria-hidden="true">→</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Temp</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16223]" style="margin-bottom: 8pt; padding-left: 108pt"><span class="mm-list-marker" aria-hidden="true">→</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>RR.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16224]" style="margin-bottom: 8pt; padding-left: 108pt"><span class="mm-list-marker" aria-hidden="true">→</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>SPo</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sub>2</sub></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16225]" style="margin-bottom: 8pt; padding-left: 108pt"><span class="mm-list-marker" aria-hidden="true">→</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>JVP.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16226]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Repeat daily.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16227]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>CBC</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16228]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Parasite count.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16229]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>LFT, RFT, clotting screen.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16230]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Treat for G negative bacteria.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16231]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Artesunate</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> I/V 2.4mg/kg @ 0, 12, 24hours’ stat dose (drugs of choice any Gestation, then daily till patient is stable).</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16232]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Quinine I/V 20mg/ kg in 5% D/W over 4 hours. Then 100mg/kg every 8 hours then oral when Pt can swallow.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16233]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Uncomplicated:</strong></u></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16234]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Admit in ward</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16235]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>&lt;2% parasitemia</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16236]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Mortality 0.1%</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16237]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Quinine 600mg 8 hourly + clindamycin 450mg 8 hourly (before 13 </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>weeks drug</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> of choice).</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16238]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>OR</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16239]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Raiment</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>4-tab</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>, B.D for 3days.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16240]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>OR</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16241]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Proguanil + Atovaquone (m</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>alar</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>one) 4 doses daily – 3 days.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16242]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Some important points about Malaria:</strong></u></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16243]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Expert advice (esp</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ecially</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> recurrent &amp; severe).</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16244]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Rapid detection negative in low </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>parasitemia</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> &amp; P – vivax.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16245]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Gold std microscopy thin/thick film.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16246]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Rapid detection </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>followed by</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> microscopy (Number of infected cells, species, stage).</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16247]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Premunition</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>: Natural immunity acquired against malaria.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16248]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Low premunition – 90% with low premunition develop anemia.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16249]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>UK population low premonition.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16250]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Relapses –</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> due to planta sequestration:</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16251]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">1.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>25 – 42 days’ average, relapse time </span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16252]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">2.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>85 </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>days</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> after quinine.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16253]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">3.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>98 days after </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Artesunate</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16254]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">4.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>63 days with artemether, </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>lumefantrine</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong> </strong></span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16255]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">5.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Weekly films –</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> reduces mortality due to recurrence.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16256]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">6.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>treatment of recurrence =&gt; </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>artesunate</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 84% success. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Artesunate</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 100mg/ day </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>for</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 7 days + clinda</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>mycin</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 45mg T</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>DS</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> – 7 days (WHO recommendation for relapse).</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16257]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Hypoglycemia exacerbation by quinine =&gt; fetal distress.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16258]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Cinchonism, 7 days’ treatment:</strong></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16259]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em>Headache.</em></span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16260]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em>Nausea.</em></span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16261]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em>Diarrhea. </em></span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16262]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em>Vomiting.</em></span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16263]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em>Blurred vision.</em></span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16264]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em>Auditory problems.</em></span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16265]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Hypoglycemia – due to hyper insulinemia.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16266]" style="margin-left: 54pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>commonest S/E of quinine.</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16267]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Infection control specialist</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> =&gt; recurrent/ severe cases.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16268]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Treatment of complications:</strong></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16269]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pulmonary edema – JVP aim of rt arterial pressure &lt;10cm H</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sub>2</sub></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>O, (it has 50% mortality)</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16270]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Anemia Hb &lt;8:</span></span></div>
