INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-09-017-0', 't-mm-09-017', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-09-017" hidden></div>
<div class="mm-heading mm-h2 mm-header-banner mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17501]" style="background-color: #2F5496; color: #FFFFFF; padding: 6px 12px; border-radius: 4px; font-weight: 700; margin-top: 8pt; margin-bottom: 4pt; padding-left: 54pt"><span class="mm-list-marker" aria-hidden="true">3.</span><span class="mm-list-body"><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>REDUCED FETAL MOVEMENTS:</strong></span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17502]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Fetal movements     es till 32 weeks then platu</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>e</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>. </span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17503]" style="text-align: center; margin-bottom: 8pt; margin-left: 72pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>C/O RFM</strong></u></span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>No RFM </strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>confirmed</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong> on history:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17504]" style="margin-bottom: 8pt; margin-left: 72pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Reassure.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Routine care.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Reporting of further episode </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Guide regarding FKC for 2 hours, Fetal movements less than 10 in 2 hours need reporting.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17505]" style="margin-bottom: 8pt; margin-left: 72pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17506]" style="margin-bottom: 8pt; margin-left: 72pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>RFM</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> &lt;10</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> in </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>2hrs.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Before 24 weeks</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Never felt movements</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>FMU to rule out </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>neuromuscular</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Abnormality.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Causes</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> of RFM</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>:</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Fetal anomaly.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Sedating drugs.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Smoking.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Steroid cover.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Anterior placenta.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Anterior spine of fetus</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>IUGR</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17507]" style="margin-bottom: 8pt; margin-left: 72pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17508]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>&gt; 28 weeks</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Detailed clinical History RF.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Age – extreme of age is R.F of IUGR</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Parity.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>DM.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>HTN.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>BOH.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Known IUGR.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Smoking. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Obesity.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>24 – 28 weeks</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>FHS auscultation.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Rule out risk factor for RFM &amp; IUGR.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>(Early onset IUGR)</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17509]" style="margin-bottom: 8pt"> </p>
