INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-09-018-2', 't-mm-09-018', 'document_html', '<div class="mm-table-scroll" role="region" tabindex="0"><table class="mm-table" style="border-collapse:collapse;margin-left:0pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;"><colgroup><col style="width:133.2pt;"><col style="width:68.65pt;"><col style="width:113.2pt;"><col style="width:95.8pt;"><col style="width:128.65pt;"></colgroup><tbody><tr><td style="white-space:pre-wrap;width:133.7pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''><u><strong>Risk assessment</strong></u></span></p><ol style="list-style-type:none;margin:0 0 0 36pt;padding:0;text-indent:-18pt;"><li data-source-marker-codepoints="U+0025 U+0031 U+002E"><span class="list-prefix" style="display:inline-flex;width:18pt;"><span class="list-marker">1.</span><span class="list-tab" aria-hidden="true" data-list-suffix="tab" style="flex:1 1 auto;min-width:0;"></span></span>@ Booking.</li><li data-source-marker-codepoints="U+0025 U+0031 U+002E"><span class="list-prefix" style="display:inline-flex;width:18pt;"><span class="list-marker">2.</span><span class="list-tab" aria-hidden="true" data-list-suffix="tab" style="flex:1 1 auto;min-width:0;"></span></span>@ Mid trimester anomaly scan.</li></ol></td><td colspan="2" style="white-space:pre-wrap;width:177.9pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"><span class="mm-run" style=''