INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-09-033-0', 't-mm-09-033', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-09-033" hidden></div>
<h2 class="mm-heading mm-h2 mm-header-banner" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19432]" style="background-color: #2F5496; color: #FFFFFF; padding: 6px 12px; border-radius: 4px; font-weight: 700; margin-top: 8pt; margin-bottom: 4pt"><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>20. </strong></span><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>ANTENATAL CORTICOSTEROID:</strong></span></h2>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19433]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Benefits:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19434]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>If given </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>within</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> 7 </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>days</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> of preterm birth</strong></u></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19435]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>  Perinatal and neonatal </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>death</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19436]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>RDS</span><span class="mm-tab" aria-hidden="true">	</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19437]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>If given in planned c section between 37-38+6 weeks </strong></u></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19438]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>NICU admission for RDS</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19439]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Uncertainty</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> in RDS</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> reduction</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19440]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> Uncertainty in TTN reduction</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>    </span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19441]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> Uncertainty</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> in overall NNU admission</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19442]" style="margin-bottom: 8pt; margin-left: 36pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19443]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>      </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19444]" style="margin-bottom: 8pt; margin-left: 36pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19445]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Risks:</strong></u></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19446]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Hypoglycemia to neonate</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19447]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Potential developmental delay</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19448]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Steroid talk:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19449]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Discussion before offering or considering steroid.</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19450]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Should involve women in discussion</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19451]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Informed decision of women should be there</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19452]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>It is Gestation related</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19453]" style="margin-bottom: 8pt; margin-left: 54pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Discussion should be based on following points</span></p>
