INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-10-002-0', 't-mm-10-002', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-10-002" hidden></div>
<div class="mm-heading mm-h3 mm-header-banner mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19769]" style="background-color: #9CC2E5; color: #FFFFFF; padding: 6px 12px; border-radius: 4px; font-weight: 700; margin-top: 8pt; margin-bottom: 4pt; padding-left: 54pt"><span class="mm-list-marker" aria-hidden="true">1.</span><span class="mm-list-body"><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>TYPES OF BIRTH SETTING</span></span></div>
