INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-10-018-0', 't-mm-10-018', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-10-018" hidden></div>
<div class="mm-heading mm-h3 mm-header-banner mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20873]" style="background-color: #9CC2E5; color: #FFFFFF; padding: 6px 12px; border-radius: 4px; font-weight: 700; margin-top: 8pt; margin-bottom: 4pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">7.</span><span class="mm-list-body"><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>OBESITY</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20874]" style="margin-bottom: 8pt; margin-left: 18pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>BMI @ booking &gt; 30 kg/m</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>2 </sup></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20875]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Fetal position assessment </strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>during labo</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>u</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>r – by USG</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20876]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Fetal monitoring</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> during labo</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>u</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>r</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20877]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">50.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>With no medical condition =&gt; as per NICE Guideline on fetal monitoring in labor</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20878]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">51.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Monitoring depends upon women’s preferences and obstetric indications.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20879]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Position During Labor:</strong></span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20880]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Depends upon</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20881]" style="margin-bottom: 8pt; margin-left: 72pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Women’s preferences</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20882]" style="margin-bottom: 8pt; margin-left: 72pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>2. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Women’s mobility</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20883]" style="margin-bottom: 8pt; margin-left: 72pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>3. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Comorbidities</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20884]" style="margin-bottom: 8pt; margin-left: 72pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>4. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Current weight</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20885]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Reduced mobility</strong></em></span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>adequate mobility</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20886]" style="margin-bottom: 8pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20887]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Left lateral </span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>as per guideline on        in 2</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>nd</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> stage of labor</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>normal women</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20888]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Equipment needed</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> in labor with BMI &gt; 30</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20889]" style="margin-bottom: 8pt; margin-left: 54pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Birthing beds – That can take safe load of 250kg</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20890]" style="margin-bottom: 8pt; margin-left: 54pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>2. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Sized appropriate</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20891]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Surgical, obstetric and anesthetic equipment</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20892]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>B.P cuffs</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20893]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Operating tables.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20894]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Lifting and lateral transfer</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20895]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Anti – embolic stockings</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20896]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Wheel chairs</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20897]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Monitoring and measuring equipment.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20898]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Referral to suitable obs</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>tetric</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong> Unit:</strong></span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20899]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">52.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>If BMI &gt; 50 @ booking</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20900]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">53.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Refer as early as possible during ANC.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20901]" style="margin-bottom: 8pt"> </p>', 0);

