INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-10-036-1', 't-mm-10-036', 'document_html', '<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22064]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Full</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>abdominal</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>and</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>vaginal</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>examination</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Preparation</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>of</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>mother</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Preparation</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>of</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>staff</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Head is</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>≤ </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1/5 palpable per abdomen (in most cases not palpable) </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Cervix is fully dilated and the membranes ruptured</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Station at l</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>evel of ischial spines or below</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Posi</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>tion of the fetal head has been </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>determined</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>USG assessment of fetal position is reliable and is recommended routinely not recommended</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Caput</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>and</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>molding</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>are</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>no</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>more</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>than</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>moderate</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>(or</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''>+</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>2)</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup> a</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pelvis</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>is</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>deemed</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>adequate</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Clear explanation given and informed consent taken and documented in women</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>’</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>s case notes</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Trust established and full cooperation sought and agreed with woman </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Appropriate analgesia is in place: for </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>m</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>id</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>pelvic</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> or rotational birth, this will usually be a regional block; a pudendal block may be acceptable depending on urgency;</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>and</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>a</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>perineal</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>block</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>may</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>be</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>suf</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>fi</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>cient</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>for</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>low</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>or</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>outlet</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>birth </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Maternal bladder has been emptied</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Indwelling catheter has been removed or balloon de</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>fl</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ated </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Aseptic technique</span><span class="mm-run" style=''font-family: "Calibri", sans-s