INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-10-037-0', 't-mm-10-037', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-10-037" hidden></div>
<h2 class="mm-heading mm-h2 mm-header-banner" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22103]" style="background-color: #2F5496; color: #FFFFFF; padding: 6px 12px; border-radius: 4px; font-weight: 700; margin-top: 8pt; margin-bottom: 4pt"><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>1</strong></span><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>3</strong></span><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>. </strong></span><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>INDUCTION OF </strong></span><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>LABOUR:</strong></span><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong> </strong></span><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>IOL</strong></span></h2>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22104]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1/5 pregnancies need IOL</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22105]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>2/3 give birth without intervention</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22106]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>15</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>% need </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>AVB</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22107]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>22%</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> end up in C</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>/S</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22108]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">323.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Most women go into labo</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>u</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>r by 42 weeks</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22109]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">324.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>@ 38 weeks all women should be offered information regarding</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22110]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Risk of pregnancies that last longer than 42 weeks.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22111]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>2. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Expectant management</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22112]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>3. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Membranes stripping</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22113]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Method </span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22114]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>benefits of spontaneous labour</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22115]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Uncomfortable, pain</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22116]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Possible bleeding</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22117]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>4. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>IOL between 41 – 42 weeks</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22118]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 13pt''><strong>Information giving before IOL:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22119]" style="margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Reason</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22120]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>2. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>When, where, how </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22121]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>3. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Support, pain relief</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22122]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>4. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Alternative to IOL</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22123]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>5. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Risk/ Benefits of IOL</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22124]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>6. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>what if IOL fails</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22125]" style="margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>7. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>prolong pregnancy IOL between 41 – 42 weeks exact timing according to patient’s wishes patient who decline =&gt; after 42 weeks</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22126]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>CTG + Amniotic Fluid =&gt; twice/ week</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22127]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>PPROM</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22128]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Before 37 weeks expectant management, to prolong till 37 weeks. In case of fetomaternal </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>indications</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> offer IOL</span></span></div>
