INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-11-001-0', 't-mm-11-001', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-11-001" hidden></div>
<h2 class="mm-heading mm-h2 mm-header-banner" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22608]" style="background-color: #2F5496; color: #FFFFFF; padding: 6px 12px; border-radius: 4px; font-weight: 700; margin-top: 8pt; margin-bottom: 4pt"><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>1.</strong></span><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>POST PARTUM HAEMORRHAGE;</strong></span><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong> </strong></span><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>PPH</strong></span></h2>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22609]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>  P</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>0</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup> </sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>PPH</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22610]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Bleeding &gt;500ml </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>within 24 hours of</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> normal</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> delivery</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> and &gt;1000ml after CS</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22611]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Minor PPH: 500 – 1000ml</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22612]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Major PPH</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22613]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Moderate 1000 – 2000</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22614]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Severe &gt;2000ml</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22615]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Secondary </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>PPH: from</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 24 hours </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>of delivery to </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>12 weeks</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> postpartum</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22616]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Most c</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ommon cause of obs</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>tetric</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>haemorrhage</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22617]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Identify risk factor </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>antenatally</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> and I/P</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22618]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Correction of anemia    </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>m</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>orbidity after PPH</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22619]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Women with risk factor =&gt; delivery in</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> a</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> unit with</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> facility of</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> blood bank</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22620]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Shock index = HR/ systolic BP =&gt; early marker </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>of h</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>a</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>emodynamic compromise</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22621]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Prophylaxis of PPH:</strong></u></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22622]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Oxytocin</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22623]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>SVD 10</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>units,</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> I/M</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22624]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>CS 5 units I/V</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>,</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>no</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> more units are beneficial.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22625]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>U</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>terine – ma</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ssage routinely – no role in </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>prophylaxis</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22626]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Tranexamic</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>acid;</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 500 – 1000</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>mg</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> (in C/S in women @ risk of PP</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>H</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>)</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22627]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Ergometrine + oxytocin without HTN reduces minor </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>haemorrhage</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> (Given in patient with risk of </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>haemorrhage</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>)</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22628]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>oxytocin =&gt; routine use </span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22629]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Er</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>g</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>o</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>met</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>r</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ine</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>, </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Tranexamic</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> acid =&gt; in women with </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>risk</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> factor.</span></span></div>
