INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-12-002-0', 't-mm-12-002', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-12-002" hidden></div>
<h2 class="mm-heading mm-h2 mm-header-banner" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24043]" style="background-color: #2F5496; color: #FFFFFF; padding: 6px 12px; border-radius: 4px; font-weight: 700; margin-top: 8pt; margin-bottom: 4pt"><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>3.WORK BASE ASSESSMENT TOOL</strong></span></h2>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24044]" style="margin-top: 12pt; margin-bottom: 12pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24045]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Workplace based assessments</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24046]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>evaluate progression through training, they link teaching learning, and assessment in a structured way.</span><br><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> Workplace based assessments identify your strengths and weaknesses.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24047]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Clinical based discussion: </strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>CBD </strong></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24048]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>tool for supervised learning events based on a trainee’s management of   patient </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>and provides</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> feedback on clinical reasoning, decision making and applied medical Knowledge in </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>relation to</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> patient care.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24049]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Mini clinical exams : </strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Mini – c</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>ex</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong> </strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong> </strong></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24050]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>supervised learning event tool evalua</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>ting a clinical encounter with </strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>patient to provide feedback on Skills essential for good clinical care e.g. history examination, clinical </strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>reasoning.</strong></span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24051]" style="margin-top: 12pt; margin-bottom: 12pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>OSATS</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>:</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> Objective Structured Assessment of Technical Skills</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24052]" style="margin-top: 12pt; margin-bottom: 12pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>A validated assessment tool to assess competency in a particular technique for a procedure fundamental to obs and gynae.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24053]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Formative assessments</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24054]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>assessment for learning used to provide feedback (mini-cex and CBD,</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>OSAT</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>)</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24055]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>record all formative OSATS in portfolio</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24056]" style="margin-top: 12pt; margin-bottom: 12pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Summative Assessments</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>: </span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24057]" style="margin-top: 12pt; margin-bottom: 12pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Assessment of learning to demonstrate competence in a clinical situation, e.g. OSATS</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24058]" style="margin-top: 12pt; margin-bottom: 12pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Formative and summative are not interchangeable, must b declared in advance either its formative or summative</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24059]" style="margin-top: 12pt; margin-bottom: 12pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>3 summative OSAT per procedure before doing it independently</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24060]" style="margin-top: 12pt; margin-bottom: 12pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>One annual OSAT till CCT</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24061]" style="margin-top: 12pt; margin-bottom: 12pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Examples/comparison of formative and summative OSAT</strong></u></span></p>
<div class="mm-table-scroll" role="region" tabindex="0"><table class="mm-table" style="border-collapse:collapse;margin-left:0pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;"><colgroup><col style="width:125.75pt;"><col style="width:125.75pt;"></colgroup><tbody><tr><td style="white-space:pre-wrap;width:125.75pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-top:12pt;margin-bottom:12pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''><strong>Formative assessment</strong></span></p></td><td style="white-space:pre-wrap;width:125.75pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-top:12pt;margin-bottom:12pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''><strong>Summative</strong></span></p></td></tr><tr><td style="white-space:pre-wrap;width:125.75pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-top:12pt;margin-bottom:12pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>Feed back</span></p></td><td style="white-space:pre-wrap;width:125.75pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-top:12pt;margin-bottom:12pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>Pass/fail, completion of training</span></p></td></tr><tr><td style="white-space:pre-wrap;width:125.75pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-top:12pt;margin-bottom:12pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>Supervised learning</span></p></td><td style="white-space:pre-wrap;width:125.75pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-top:12pt;margin-bottom:12pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>Assessment of performance</span></p></td></tr><tr><td style="white-space:pre-wrap;width:125.75pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-top:12pt;margin-bottom:12pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>Annual job appraisal</span></p></td><td style="white-space:pre-wrap;width:125.75pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-top:12pt;margin-bottom:12pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>Theory test</span></p></td></tr><tr><td style="white-space:pre-wrap;width:125.75pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-top:12pt;margin-bottom:12pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>peer observation</span></p></td><td style="white-space:pre-wrap;width:125.75pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-top:12pt;margin-bottom:12pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>MRCOG 1,2,3</span></p></td></tr><tr><td style="white-space:pre-wrap;width:125.75pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-top:12pt;margin-bottom:12pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>Mock OSCE</span></p></td><td style="white-space:pre-wrap;width:125.75pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-top:12pt;margin-bottom:12pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>MRCOG OSCE</span></p></td></tr><tr><td style="white-space:pre-wrap;width:125.75pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-top:12pt;margin-bottom:12pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>Induction interview</span></p></td><td style="white-space:pre-wrap;width:125.75pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-top:12pt;margin-bottom:12pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>Job interview/recruitment interview</span></p></td></tr></tbody></table></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24062]" style="margin-top: 12pt; margin-bottom: 12pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>NOTES: </strong></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24063]" style="margin-top: 12pt; margin-bottom: 12pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Non-technical skills for surgeons This is the cognitive and interpersonal skills, e.g. to see and making leadership team working. The tool provides a framework and terminology for giving feedback under the following headings. Situational Awareness, Decision Making, Communication, Teamwork, Leadership </span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24064]" style="margin-top: 12pt; margin-bottom: 12pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Norm reference assessment</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>:</strong></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24065]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Cambria", sans-serif; font-size: 12pt''></span><span class="mm-run" style=''font-family: "Cambria", sans-serif; font-size: 12pt''>A norm-referenced assessment is a type of standardized test that ranks test-takers against a peer group (norm group)</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24066]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Cambria", sans-serif; font-size: 12pt''>Students are compared to each other</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24067]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Cambria", sans-serif; font-size: 12pt''>Fixed no of students fail each year</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24068]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Cambria", sans-serif; font-size: 12pt''>Candidates ability influence standard</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24069]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Cambria", sans-serif; font-size: 12pt''>Standards are not known in advance </span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24070]" style="margin-bottom: 8pt; margin-left: 18pt"><span class="mm-run" style=''font-family: "Cambria", sans-serif; font-size: 12pt''><strong>Criterion reference standard</strong></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24071]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Cambria", sans-serif; font-size: 12pt''>evaluates a student''s knowledge and skills against fixed, predetermined standards or learning objectives, rather than comparing them to peers.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24072]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Cambria", sans-serif; font-size: 12pt''>Failure rates vary</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24073]" style="margin-top: 12pt; margin-bottom: 12pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24074]" style="margin-top: 12pt; margin-bottom: 12pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24075]" style="margin-top: 12pt; margin-bottom: 12pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24076]" style="margin-top: 12pt; margin-bottom: 12pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24077]" style="margin-top: 12pt; margin-bottom: 12pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24078]" style="margin-top: 12pt; margin-bottom: 12pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24079]" style="margin-top: 12pt; margin-bottom: 12pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24080]" style="margin-top: 12pt; margin-bottom: 12pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24081]" style="margin-top: 12pt; margin-bottom: 12pt"> </p>
